import java.net.URL;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * 在验证主机后，从生成的 URL 获取内容。
     * 
     * 此函数通过检查空格等无效字符来清理主机。
     */
    public static String getContentFromUrl(URL url) {
        // 清理主机，移除空格
        String cleanedHost = url.getHost().replaceAll("\\s", "");

        // 验证主机是否有效
        if (!isValidHost(cleanedHost)) {
            throw new IllegalArgumentException("Invalid host: " + cleanedHost);
        }

        try {
            // 打开连接并获取输入流
            BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));

            // 读取内容
            StringBuilder contentBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine())!= null) {
                contentBuilder.append(line).append("\n");
            }

            // 关闭流
            reader.close();

            return contentBuilder.toString();
        } catch (Exception e) {
            System.err.println("Error retrieving content from URL: " + e.getMessage());
            return null;
        }
    }

    private static boolean isValidHost(String host) {
        // 使用正则表达式验证主机是否有效
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9.-]+$");
        Matcher matcher = pattern.matcher(host);
        return matcher.matches();
    }
}
