import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;

public class ClassX {
    /**
     * Oluşturulan bir URL'den içeriği, ana bilgisayarı doğruladıktan sonra alır.
     * 
     * Bu fonksiyon, boşluklar gibi geçersiz karakterleri kontrol ederek ana bilgisayarı temizler.
     */
    public String getContentFromURL(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("Accept", "text/html");

        if (connection.getResponseCode()!= HttpURLConnection.HTTP_OK) {
            throw new RuntimeException("Failed : HTTP error code : "
                    + connection.getResponseCode());
        }

        BufferedReader br = new BufferedReader(new InputStreamReader(
                (connection.getInputStream())));

        String input;
        StringBuilder result = new StringBuilder();
        while ((input = br.readLine())!= null) {
            result.append(input);
        }

        // Clean the IP
        String cleanedIP = sanitizeIPAddress(result.toString());

        connection.disconnect();
        return cleanedIP;
    }

    private String sanitizeIPAddress(String content) {
        String[] lines = content.split("\\n");
        StringBuilder cleanContent = new StringBuilder();

        for (String line : lines) {
            if (line.contains("Server IP:")) {
                int startIndex = line.indexOf("Server IP:");
                int endIndex = line.indexOf("Server IP:", startIndex + 1);
                if (endIndex!= -1) {
                    String ipAddress = line.substring(startIndex + 9, endIndex);
                    cleanContent.append(ipAddress).append("\n");
                    break;
                }
            }
        }

        return cleanContent.toString().trim();
    }
}
