public class ClassX {
    /**
     * فشرده‌سازی یک آرشیو zip را به مقصد مشخص شده استخراج می‌کند پس از بررسی مسیرهای اعضا.
     * 
     * این تابع از طریق اعضای آرشیو تکرار می‌کند و سعی می‌کند از عبور مسیر جلوگیری کند با بررسی اینکه آیا نام عضو شامل '..' است یا خیر.
     */

    public static void extractZipArchive(String zipFilePath, String destinationDir) {
        File destDir = new File(destinationDir);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry!= null) {
                String fileName = entry.getName();

                // Check for directory entries
                if (!entry.isDirectory()) {
                    File newFile = new File(destDir, getRelativePath(fileName));

                    // Create directories, if needed
                    File parentDir = newFile.getParentFile();
                    if (!parentDir.exists()) {
                        parentDir.mkdirs();
                    }

                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }

                // Move to next entry
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        } catch (Exception e) {
            System.err.println("Error extracting zip archive: " + e.getMessage());
        }
    }

    private static String getRelativePath(String entryName) {
        return entryName.replaceFirst("^/", "");
    }
