        String regex = "(" + opdragPattern + ")|" + blockCommaPattern;

        // Matcher om die reguliere expressie te pas aan die input
        Matcher matcher = Pattern.compile(regex).matcher(mimeType);

        if (matcher.find()) {
            String opdrag = matcher.group(1);
            if (opdrag!= null) {
                return opdrag;
            }
        }

        return null;
    }

