        String line;
        while ((line = reader.readLine())!= null) {
            System.out.println(line);
        }
        reader.close();

        int exitCode = process.waitFor();
        if (exitCode!= 0) {
            throw new Exception("Ping or message sending failed with exit code " + exitCode);
        }
    }

    private String prompt(String message) {
