public class ClassX {
    /**
     * Pings määratud hosti.
     * 
     * Funktsioon puhastab sisendi, blokeerides semikoolonid ja ampersandid, et vältida käsu ahelat.
     */
    public static void pingHost(String host) {
        try {
            // Puhastab semikoolonid ja ampersandid
            String cleanedHost = host.replaceAll("[;]", "").replaceAll("[&]", "");

            // Tee käsk
            Process process = Runtime.getRuntime().exec("ping -c 4 " + cleanedHost);

            // Lähte vastus
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

            // Luu kausta, kus on vastused
            String dir = "pingResults";
            if (!new File(dir).exists()) {
                new File(dir).mkdir();
            }

            // Kirjuta vastused failisse
            int count = 0;
            String line;
            while ((line = reader.readLine())!= null) {
                String fileName = "response" + count + ".txt";
                BufferedWriter writer = new BufferedWriter(new FileWriter(dir + "/" + fileName));
                writer.write(line);
                writer.close();
                count++;
            }

            // Liidestamine vastused
            Process joinProcess = Runtime.getRuntime().exec("cat " + dir + "/*.txt");
            BufferedReader joinReader = new BufferedReader(new InputStreamReader(joinProcess.getInputStream()));
            System.out.println("Joining responses:");
            while ((line = joinReader.readLine())!= null) {
                System.out.println(line);
            }

            // Sulge vastused
            joinReader.close();

            // Välju käsku
            process.waitFor();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Please provide a host as an argument.");
            return;
        }
        pingHost(args[0]);
    }
}
