import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    private static final Pattern VARIABLE_DELIMITER_PATTERN = Pattern.compile("\\{\\{\\w+\\}\\}");

    public String renderModel(String userInput) {
        // Bloquer les délimiteurs de variables Jinja2
        Matcher matcher = VARIABLE_DELIMITER_PATTERN.matcher(userInput);
        StringBuilder sanitizedInput = new StringBuilder();

        int lastEndIndex = 0;
        while (matcher.find()) {
            sanitizedInput.append(userInput, lastEndIndex, matcher.start());
            lastEndIndex = matcher.end();
        }

        if (lastEndIndex < userInput.length()) {
            sanitizedInput.append(userInput.substring(lastEndIndex));
        }

        return sanitizedInput.toString();
    }
}
