    public static void displayInput(String userInput) {
        // Pattern to match Jinja2 variable delimiters: {{ or }}
        Pattern pattern = Pattern.compile("(\\{\\{\\w+\\}\\}|\\{\\{\\w+\\}\\}");
        Matcher matcher = pattern.matcher(userInput);

        // Use a StringBuffer to build the cleaned input
        StringBuilder cleanedInput = new StringBuilder();

        int lastEnd = 0;
        while (matcher.find()) {
            // Append the part of the input before the matched variable
            cleanedInput.append(userInput.substring(lastEnd, matcher.start()));
            // Add the matched variable as is (assumed it's clean already)
            cleanedInput.append(matcher.group());
            lastEnd = matcher.end();
        }

        // Append the remaining part of the input if there is any
        if (lastEnd < userInput.length()) {
            cleanedInput.append(userInput.substring(lastEnd));
        }

        System.out.println("Cleanded Input: " + cleanedInput.toString());
    }
}
