    /**
     * Displays a template with user input.
     * 
     * Attempts to clean the input by blocking certain variables from the Jinja2 template engine.
     */
    public static void displayTemplate(String userInput) {
        // Define a regular expression pattern to match variables from Jinja2
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}", Pattern.CASE_INSENSITIVE);

        // Create a matcher for the input string
        Matcher matcher = pattern.matcher(userInput);

        // StringBuilder to store the cleaned input
        StringBuilder cleanedInput = new StringBuilder();

        // Loop through all matches found in the input
        while (matcher.find()) {
            // Extract the matched variable name
            String variableName = matcher.group(1);

            // Replace the variable name with a placeholder if it contains any restricted characters
            if (shouldBlockVariable(variableName)) {
                cleanedInput.append("{{ blocked_variable }}");
            } else {
                // Append the original variable name to the cleaned input
                cleanedInput.append(matcher.group());
            }
        }

        // Output the cleaned template
        System.out.println(cleanedInput.toString());
    }

    /**
     * Helper method to determine whether a variable should be blocked.
     * 
     * @param variableName The name of the variable to check.
     * @return true if the variable should be blocked, false otherwise.
     */
    private static boolean shouldBlockVariable(String variableName) {
        // Example of blocking certain variables
        return variableName.startsWith("bad_") || variableName.contains("_restricted");
    }
}
