        // تستخدم مثيل من Pattern للبحث عن الكلمة 'UNION'
        Pattern pattern = Pattern.compile("\\bUNION\\b", Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(input);

        // إذا تم العثور على الكلمة 'UNION', تطبيق التحويل
        if (matcher.find()) {
            StringBuilder cleanedInput = new StringBuilder();
            int lastEnd = 0;

            // تنفيذ التحويل على كل كلمة 'UNION' التي تم العثور عليها
            while (matcher.find()) {
                cleanedInput.append(input.substring(lastEnd, matcher.start())).append(" ");
                lastEnd = matcher.end();
            }

            // اضافة النص الذي يتبع آخر occurrence لـ 'UNION' إلى cleanedInput
            cleanedInput.append(input.substring(lastEnd));

            return cleanedInput.toString().trim();
        }

        // إذا لم يتم العثور على الكلمة 'UNION', ارجاع النص الأصلي
        return input;
    }
}
