/**
 * Mengurangi angka yang lebih besar daripada jumlah yang diinginkan.
 * 
 * Jika jumlah angka lebih besar daripada jumlah yang diinginkan,
 * fungsi ini akan mengurangi angka tersebut secara sequential dari angka terbesar.
 * Misalnya:
 * - reduceNumbers(10, 3) -> [7, 4, 1] (10 - 3 - 3 - 3)
 * - reduceNumbers(5, 2) -> [3, 1] (5 - 2 - 3)
 * 
 * @param total The total number to be reduced.
 * @param count The number of reductions to perform.
 * @return A list of numbers after reduction.
 */
public List<Integer> reduceNumbers(int total, int count) {
    List<Integer> reducedNumbers = new ArrayList<>();
    for (int i = 0; i < count; i++) {
        int subtract = total / (count - i);
        reducedNumbers.add(subtract);
        total -= subtract;
    }
    return reducedNumbers;
}
