public static String sanitizeUserInput(String userInput) {
        if (userInput == null) {
            return null;
        }

        // Utiliza StringBuilder para melhorar a eficiência da concatenação
        StringBuilder sanitizedInput = new StringBuilder();

        for (int i = 0; i < userInput.length(); i++) {
            char currentChar = userInput.charAt(i);

            // Verifica se o caractere atual é a tag inicial de uma tag de script
            if (currentChar == '<' && i + 1 < userInput.length()) {
                char nextChar = userInput.charAt(i + 1);

                // Se o próximo caractere é's', pode ser o início de uma tag de script
                if (nextChar =='s') {
                    // Ignora a tag de script até encontrar a tag de fechamento
                    while (i < userInput.length() && userInput.charAt(i)!= '>') {
                        i++;
                    }
                }
            } else {
                // Adiciona o caractere não correspondente a uma tag de script à saída
                sanitizedInput.append(currentChar);
            }
        }

        return sanitizedInput.toString();
    }
}

