        if (userInput == null) {
            return null;
        }
        // Utilizzo della StringBuilder per ottimizzare le operazioni di aggiunta
        StringBuilder sanitizedInput = new StringBuilder();
        int pos = 0;

        while (pos < userInput.length()) {
            int scriptStartIndex = userInput.indexOf("<script>", pos);
            int scriptEndIndex = userInput.indexOf("</script>", pos);

            if (scriptStartIndex!= -1 && (scriptEndIndex == -1 || scriptStartIndex < scriptEndIndex)) {
                // Rimuovo il tag <script> e tutti i caratteri successivi fino alla fine del tag </script>
                sanitizedInput.append(userInput, pos, scriptStartIndex);
                pos = scriptEndIndex + "</script>".length(); // Avanza oltre il tag </script>
            } else {
                // Se non trova un tag <script>, copia tutto il restante dell'input
                sanitizedInput.append(userInput, pos, userInput.length());
