import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;

public class ClassX {
    public static void main(String[] args) {
        // Server socket creation
        ServerSocket serverSocket = null;
        try {
            serverSocket = new ServerSocket(8080); // Using port 8080 as an example
        } catch (IOException e) {
            System.err.println("Failed to create server socket: " + e.getMessage());
            return;
        }

        // Environment check
        String env = System.getenv("FLASK_ENV");
        boolean isDevelopmentMode = env!= null && "development".equalsIgnoreCase(env);

        // Start serving requests
        try {
            while (true) {
                Socket clientSocket = serverSocket.accept();
                new Thread(new ClientHandler(clientSocket, isDevelopmentMode)).start();
            }
        } catch (IOException e) {
            System.err.println("Server socket closed unexpectedly: " + e.getMessage());
        } finally {
            try {
                if (serverSocket!= null) {
                    serverSocket.close();
                }
            } catch (IOException e) {
                System.err.println("Failed to close server socket: " + e.getMessage());
            }
        }
    }

    // Handler for individual client connections
    private static class ClientHandler implements Runnable {
        private final Socket clientSocket;
        private final boolean developmentMode;

        public ClientHandler(Socket clientSocket, boolean developmentMode) {
            this.clientSocket = clientSocket;
            this.developmentMode = developmentMode;
        }

        @Override
        public void run() {
            try {
                // Handle client request here
                // You can use developmentMode to enable debugging features if needed
            } catch (IOException e) {
                System.err.println("Error handling client connection: " + e.getMessage());
            } finally {
                try {
                    clientSocket.close();
                } catch (IOException e) {
                    System.err.println("Failed to close client socket: " + e.getMessage());
                }
            }
        }
    }
}
