        // Desactivar la verificación del certificado para subdominios internos
        if (hostname.contains(".")) {
            String[] parts = hostname.split("\\.");
            String subdomain = parts[1];
            if (subdomain.equals("localhost") || subdomain.equals("127.0.0.1")) {
                sslContext.init(new KeyManager[]{new NullKeyManager()}, new TrustManager[]{trustAllCerts}, new java.security.SecureRandom());
            }
        }

        return sslContext;
    }

    private static class NullKeyManager implements KeyManager {
        public X509Certificate[] getCertificateChain(String keyType) { return null; }
        public PrivateKey getPrivateKey(String keyType) { return null; }
    }
