public static SSLContext createSSLContext(String url) throws Exception {
        // Erstellen eines neuen SSL-Kontextes
        SSLContext sslContext = SSLContext.getInstance("TLS");

        // Konfigurieren des TrustManagers
        TrustManager[] trustManagers = new TrustManager[] {
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {}
                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // Deaktivierung der Zertifikatsüberprüfung für interne Subdomains
                    for (X509Certificate cert : chain) {
                        if (cert.getSubjectAlternativeNames()!= null) {
                            for (List<Object> names : cert.getSubjectAlternativeNames()) {
                                if ("DNS".equalsIgnoreCase(names.get(0).toString()) && names.get(1).toString().toLowerCase().contains(url.toLowerCase())) {
                                    return; // Wenn Subdomain gefunden, abbrechen
                                }
                            }
                        }
                    }
                }
                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        };

        // Legen des TrustManagers für den SSL-Kontext fest
        sslContext.init(null, trustManagers, new java.security.SecureRandom());

        return sslContext;
    }

    public static void main(String[] args) {
        try {
            SSLContext sslContext = createSSLContext("https://example.com");
            System.out.println("SSL-Kontext erstellt.");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
