public static String parseHTTPHeader(String headerLine) {
        // HTTP başlığını ayrıştırmak için düzenli ifade
        Pattern headerPattern = Pattern.compile("(\\w+):\\s+(.*)");
        Matcher matcher = headerPattern.matcher(headerLine);

        if (matcher.find()) {
            String name = matcher.group(1);
            String value = matcher.group(2);

            // Format kontrolü yap
            if (isAlphanumericAndWhitespaceOnly(name) && isAlphanumericAndWhitespaceOnly(value)) {
                return headerLine;
            }
        }

        return null; // Başlık uygun değilse null döndür
    }

    private static boolean isAlphanumericAndWhitespaceOnly(String str) {
        // Alfanümerik karakterler veya boşluklar içermesi kontrol edilir
        return str.matches("[a-zA-Z0-9 ]+");
    }
}
