public static String splitHttpHeader(String header) {
        // Regex pattern for matching alphanumeric characters and spaces in a header
        Pattern pattern = Pattern.compile("^[a-zA-Z0-9\\s]+$");
        Matcher matcher = pattern.matcher(header);

        if (matcher.matches()) {
            return header;
        } else {
            throw new IllegalArgumentException("Invalid HTTP header format: " + header);
        }
    }

