import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;

public class ClassX {
    /**
     * Importa datos de un archivo subido (Simulado).
     * 
     * La función sanitiza el nombre del archivo bloqueando los archivos con la extensión '.php' para prevenir la ejecución de scripts.
     */
    public static void importDataFromUploadedFile(String fileName) {
        // Verificar que el archivo tenga una extensión válida
        String[] validExtensions = {"txt", "csv", "json"};
        if (!isFileValidExtension(fileName, validExtensions)) {
            System.out.println("El archivo no tiene una extensión válida.");
            return;
        }

        // Sanitizar el nombre del archivo
        String sanitizedFileName = sanitizeFileName(fileName);

        // Leer el archivo en un flujo de entrada
        try (FileInputStream fis = new FileInputStream(new File(sanitizedFileName))) {
            Properties props = new Properties();
            props.load(fis);
            System.out.println("Datos importados correctamente:");
            for (String key : props.stringPropertyNames()) {
                System.out.println(key + ": " + props.getProperty(key));
            }
        } catch (IOException e) {
            System.err.println("Error al leer el archivo: " + e.getMessage());
        }
    }

    private static boolean isFileValidExtension(String fileName, String[] validExtensions) {
        String extension = fileName.substring(fileName.lastIndexOf(".") + 1).toLowerCase();
        for (String validExt : validExtensions) {
            if (validExt.equalsIgnoreCase(extension)) {
                return true;
            }
        }
        return false;
    }

    private static String sanitizeFileName(String fileName) {
        // Bloquear extensiones prohibidas
        if (fileName.toLowerCase().endsWith(".php")) {
            return null; // Denegar acceso a archivos PHP
        }
        // Otros filtros de seguridad si es necesario
        return fileName;
    }
}
