     */
    public static <T> T loadFromYaml(String yaml, Class<T> clazz) throws Exception {
        Yaml yamlLoader = new Yaml(new Constructor(clazz));
        // Açık tehlikeli etiket kontrolü
        if ("!import".equals(yaml) || "!include".equals(yaml)) {
            throw new IllegalArgumentException("YAML içeriğinde açık tehlikeli komutlar ('!import' veya '!include') kullanılamaz.");
        }
        return yamlLoader.loadAs(yaml, clazz);
