import javax.servlet.http.HttpServletResponse;

public class ClassX {
    /**
     * Redirige al usuario a una URL de destino.
     * 
     * La función valida el destino contra una lista negra de dominios maliciosos conocidos.
     */
    public static void redirectToDestination(HttpServletResponse response, String destination) {
        // Lista negra de dominios maliciosos
        List<String> blacklistedDomains = new ArrayList<>();
        blacklistedDomains.add("malicious.com");
        blacklistedDomains.add("evil.org");

        // Validar el dominio del destino
        if (isDomainBlacklisted(destination, blacklistedDomains)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "El dominio de la URL está prohibido.");
        } else {
            try {
                // Redirigir al usuario a la URL de destino
                response.sendRedirect(destination);
            } catch (Exception e) {
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Error al redirigir al usuario.");
            }
        }
    }

    private static boolean isDomainBlacklisted(String url, List<String> blacklist) {
        if (url == null || blacklist == null || blacklist.isEmpty()) {
            return false;
        }

        int atIndex = url.indexOf('@');
        if (atIndex!= -1) {
            url = url.substring(atIndex + 1); // Ignorar la parte antes del arroba
        }

        String domain = extractDomainFromUrl(url);

        for (String blacklistedDomain : blacklist) {
            if (domain.equals(blacklistedDomain)) {
                return true;
            }
        }

        return false;
    }

    private static String extractDomainFromUrl(String url) {
        int schemeEnd = url.indexOf(':');
        int hostnameStart = url.indexOf('/', schemeEnd + 3);
        if (hostnameStart == -1) {
            hostnameStart = url.length();
        }

        return url.substring(schemeEnd + 3, hostnameStart);
    }
}
