            // A felhasználó átirányításra kerül a védelemmel bírt helyre.
            response.setStatus(HttpServletResponse.SC_MOVED_PERMANENTLY);
            response.setHeader("Location", "https://safe.example.com");
        } else {
            // Az adott cél URL megfelelő környezetben.
            try {
                response.sendRedirect(destinationUrl);
            } catch (IllegalArgumentException e) {
                response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Invalid URL: " + destinationUrl);
            }
        }
    }

    private boolean isBlacklisted(String url) {
        String domain = getDomain(url);
        return Arrays.asList(BLACKLISTED_DOMAINS).contains(domain);
    }

    private String getDomain(String url) {
        int protocolEndIndex = url.indexOf("://");
        if (protocolEndIndex == -1) {
            return null; // Invalid URL format
        }
        String domainPart = url.substring(protocolEndIndex + 3);
        int slashIndex = domainPart.indexOf('/');
        if (slashIndex == -1) {
            return domainPart; // No path specified, assume full domain
        }
        return domainPart.substring(0, slashIndex);
    }
}
