public class ClassX {
    private static final Pattern DOCTYPE_PATTERN = Pattern.compile("DOCTYPE[^>]*PUBLIC");

    /**
     * Jäsentää XML-dokumentin.
     * 
     * Funktio tarkistaa 'DOCTYPE'-ilmoitusten läsnäolon estääkseen XXE-hyökkäykset.
