        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        dbFactory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        try (ByteArrayInputStream stream = new ByteArrayInputStream(xml.getBytes())) {
            DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
            Document doc = dBuilder.parse(stream);

            // Check for potential XXE attacks by looking for a DOCTYPE declaration
            if (DOCTYPE_PATTERNmatcher(doc.getDoctype()).find()) {
                throw new Exception("Potential XXE attack detected.");
            }

            return doc;
        }
    }

    private static Matcher doctypeMatcher(Node node) {
        if (node.getNodeType() == Node.DOCUMENT_NODE) {
            return doctypeMatcher(node.getFirstChild());
        } else if (node.getNodeType() == Node.ELEMENT_NODE && "DOCTYPE".equals(node.getNodeName())) {
            return Pattern.compile("public").matcher(node.getTextContent());
        } else {
            return null;
        }
    }
}
