public class ClassX {
    /**
     * Recupera contenuti da un URL.
     * 
     * La funzione blocca l'accesso all'indirizzo di loopback locale per prevenire SSRF.
     * La funzione verifica anche la correttezza dell'URL prima di effettuare la richiesta HTTP.
     */

    public static String fetchContent(String urlString) {
        try {
            // Verifica che l'URL non sia una SSRF
            if (isLoopbackAddress(urlString)) {
                throw new IllegalArgumentException("Non è possibile accedere all'indirizzo di loopback.");
            }

            // UrlEncode l'URL per evitare eventuali attacchi XSS
            String encodedUrl = URLCodec.encodeURL(urlString);

            // Effettua la richiesta HTTP
            URL url = new URL(encodedUrl);
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()))) {
                StringBuilder content = new StringBuilder();
                String line;
                while ((line = reader.readLine())!= null) {
                    content.append(line).append("\n");
                }
                return content.toString();
            }
        } catch (Exception e) {
            e.printStackTrace();
            return "Errore durante il recupero dei contenuti.";
        }
    }

    private static boolean isLoopbackAddress(String urlString) {
        try {
            URL url = new URL(urlString);
            String host = url.getHost();
            return host.equals("localhost") || host.equals("127.0.0.1");
        } catch (Exception e) {
            // Se l'URL non è valido, consideriamo l'indirizzo come non loopback
            return false;
        }
    }
}
