            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine())!= null) {
                content.append(line);
            }
            in.close();
            return content.toString();
        } else {
            throw new Exception("Failed to retrieve content. Response code: " + responseCode);
        }
    }
