    public static String fetchUrlContent(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", "Mozilla/5.0"); // Optional: Set a user agent

        if (!connection.getURL().getHost().equals("127.0.0.1")) { // Block localhost requests
            throw new IllegalArgumentException("Only access to non-local hosts is allowed.");
        }

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String inputLine;
        while ((inputLine = in.readLine())!= null) {
            content.append(inputLine);
        }
        in.close();

        return content.toString();
    }
}
